// /frontend-react/src/components/HeaderBar.js (REVISED)

import React from 'react';

const HeaderBar = ({ title, onBackClick, onMenuClick, isEasyMode }) => ( // ADD onMenuClick PROP
    <div style={{
        display: 'flex',
        alignItems: 'center',
        padding: '15px 20px',
        backgroundColor: '#f8f9fa', 
        borderBottom: '1px solid #e0e0e0',
        position: 'relative',
        position: 'sticky',
        top: 0,
        zIndex: 5,
    }}>
        {onBackClick && (
            // Back Button (Left side)
            <button
                onClick={onBackClick}
                // ... (styling remains the same) ...
            >
                <span role="img" aria-label="Back">◀️</span>
            </button>
        )}
        
        {/* Title (Center) */}
        <h2 style={{
            fontSize: isEasyMode ? '36px' : '24px',
            margin: 0,
            color: '#333',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            flexGrow: 1, // Allows title to take up center space
            textAlign: 'center',
            marginLeft: onBackClick ? '-45px' : '0' // Visually center despite back button
        }}>
            {title}
        </h2>
        
        {/* Menu Icon (Right side) */}
        {onMenuClick && (
            <button
                onClick={onMenuClick}
                style={{
                    padding: '8px',
                    backgroundColor: 'transparent',
                    border: 'none',
                    borderRadius: '50%',
                    cursor: 'pointer',
                    fontSize: isEasyMode ? '30px' : '20px',
                    color: '#333',
                    marginLeft: '15px',
                    transition: 'background-color 0.2s',
                    flexShrink: 0,
                }}
                onMouseOver={e => e.currentTarget.style.backgroundColor = '#ddd'}
                onMouseOut={e => e.currentTarget.style.backgroundColor = 'transparent'}
            >
                <span role="img" aria-label="Menu">☰</span>
            </button>
        )}
    </div>
);

export default HeaderBar;
